 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    # Extend diagonal sequences of non-background cells by continuing the
    # direction established by two same-color cells. Existing cells block rays.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                pr, pc = r - dr, c - dc
                nr, nc = r + dr, c + dc
                if not (0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color):
                    continue
                while 0 <= nr < h and 0 <= nc < w and out[nr][nc] == background:
                    out[nr][nc] = color
                    nr += dr
                    nc += dc
    return out


